<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { apiGet, apiRequest } from '../services/api.js'
import { useAuthStore } from '../stores/auth.js'
import FormPanel from '../components/FormPanel.vue'
import { label } from '../utils.js'
import SidePanel from '../components/SidePanel.vue'
import AppIcon from '../components/AppIcon.vue'
import { useWorkspaceStore } from '../stores/workspace.js'
const workspace = useWorkspaceStore()
const auth = useAuthStore(), route = useRoute(), router = useRouter(), contents = ref([]), companies = ref([]), company = ref(auth.user.company_id), initial = ref({}), editing = ref(null), reviews = ref({}), error = ref(''), notice = ref(''), busy = ref(false), formKey = ref(0), formOpen = ref(false)
const clinical = computed(() => ['doctor', 'nurse'].includes(auth.user.role))
const suffix = () => '?' + new URLSearchParams({ company_id: company.value })
const fields = [ { name: 'title', label: 'Título', max: 180 }, { name: 'category', label: 'Finalidade', options: [{ value: 'platform', label: 'Como usar a plataforma' }, { value: 'aps', label: 'Continuidade da APS · revisão clínica obrigatória' }] }, { name: 'duration_seconds', label: 'Duração prevista em segundos', type: 'number', min: 1, default: 90 }, { name: 'video_url', label: 'Endereço HTTPS do vídeo gravado', type: 'url', optional: true, max: 2000, help: 'MP4/WebM para reprodução na página, ou link para o vídeo publicado. Sem vídeo, o texto continua disponível.' }, { name: 'summary', label: 'Apresentação acolhedora', type: 'textarea', max: 2000, wide: true }, { name: 'transcript', label: 'Roteiro / transcrição acessível', type: 'textarea', max: 10000, wide: true } ]
async function load() { contents.value = await apiGet('/management/contents' + suffix()) }
function clear() { editing.value = null; initial.value = {}; formKey.value++ }
function edit(c) { editing.value = c; initial.value = { ...c }; formKey.value++; formOpen.value = true }
async function save(data) { busy.value = true; error.value = ''; notice.value = ''; try { await apiRequest('/management/contents' + (editing.value ? '/' + editing.value.id : '') + suffix(), editing.value ? 'PUT' : 'POST', { ...data, ...(editing.value ? { version: Number(editing.value.version) } : {}) }); clear(); await load(); formOpen.value = false; router.replace({ path: route.path }); notice.value = 'Rascunho salvo. Alterações retiram a publicação anterior e exigem nova revisão.' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function publish(c) { busy.value = true; error.value = ''; try { await apiRequest(`/management/contents/${c.id}/publish` + suffix(), 'POST', { version: Number(c.version), review_note: reviews.value[c.id] || '' }); await load(); notice.value = 'Conteúdo revisado e publicado na biblioteca dos beneficiários.' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function change() { clear(); error.value = ''; busy.value = true; if (auth.user.management_level !== 'none') workspace.companyId = Number(company.value); try { await load() } catch (e) { contents.value = []; error.value = e.message } finally { busy.value = false } }
watch(() => route.query.new, value => { if (value === 'content') { clear(); formOpen.value = true } })
onMounted(async () => { busy.value = true; try { if (auth.user.management_level !== 'none') { await workspace.ensure(auth.user); companies.value = workspace.companies; company.value = workspace.companyId } else companies.value = [{ id: auth.user.company_id, name: 'Minha indústria de atuação' }]; await load(); formOpen.value = route.query.new === 'content' } catch (e) { error.value = e.message } finally { busy.value = false } })
</script>
<template><p class="eyebrow">EDUCAÇÃO RÁPIDA E ACOLHEDORA</p><div class="page-heading"><h1>Conteúdos educativos</h1><button class="btn btn-success" :disabled="busy" @click="clear(); formOpen = true"><AppIcon name="plus" :size="18" /> Novo conteúdo</button></div><p class="text-secondary">Roteiros, vídeos curtos e orientações de uso. Publicação de conteúdos APS depende de revisão profissional.</p><label v-if="companies.length > 1" for="editor-company" class="form-label">Indústria</label><select v-if="companies.length > 1" id="editor-company" v-model="company" class="form-select mb-4" :disabled="busy" @change="change"><option v-for="c in companies" :key="c.id" :value="c.id">{{ c.name }}</option></select><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p><SidePanel :open="formOpen" :title="editing ? 'Editar conteúdo' : 'Preparar conteúdo educativo'" :busy="busy" @close="formOpen = false; $router.replace({ path: $route.path })"><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><FormPanel :key="formKey" :fields="fields" :initial="initial" :busy="busy" submit-label="Salvar rascunho" @submit="save" /></SidePanel><section><h2 class="h4">Biblioteca editorial</h2><p v-if="!contents.length">Nenhum conteúdo cadastrado.</p><div class="row g-3"><div v-for="c in contents" :key="c.id" class="col-lg-6"><article class="card card-body h-100"><span class="small text-secondary">{{ c.category === 'aps' ? 'APS' : 'Tutorial da plataforma' }} · {{ label(c.status) }}</span><h3 class="h5 mt-2">{{ c.title }}</h3><p>{{ c.summary }}</p><details class="mb-3"><summary>Conferir roteiro e transcrição</summary><p class="mt-2" style="white-space: pre-wrap">{{ c.transcript }}</p><a v-if="c.video_url" :href="c.video_url" target="_blank" rel="noopener noreferrer">Conferir vídeo</a></details><button class="btn btn-outline-secondary align-self-start mb-3" :disabled="busy" @click="edit(c)">Editar rascunho</button><template v-if="c.status !== 'published' && (clinical || c.category === 'platform')"><label :for="`review-${c.id}`" class="form-label">Registro da revisão antes de publicar</label><textarea :id="`review-${c.id}`" v-model="reviews[c.id]" class="form-control mb-2" maxlength="1000" /><button class="btn btn-success" :disabled="busy || !reviews[c.id]?.trim()" @click="publish(c)">Revisar e publicar</button></template><p v-else-if="c.status !== 'published'" class="small text-secondary">Aguardando revisão de médico ou enfermeiro.</p><p v-else class="small text-success">Publicado · revisão registrada pelo usuário #{{ c.reviewed_by }}</p></article></div></div></section></template>
